// ═══════════════════════════════════════════════════════════════════════════════
// FILE: js/nz-chapter-data-full.js
// NihongoZen — Full Level-wise Chapter Vocabulary Data (N5 – N1)
//
// Combines the previous chapters.js + vocabLevel.js pair into a single file.
// Word lists are merged directly into each chapter object, so no runtime
// merge step is needed.
//
// Structure: window.NZChapterData[level][chapterIndex] = { ch, title, topic, words }
// N2 chapters additionally carry { week, day } and, for the 7th-day review
// chapter of each week, { isTest: true, quiz: [{ id, question, options, answer, note }] }
// (words is [] on those chapters — quiz is the payload). This mirrors the
// { id, question, options, answer } shape already used by quizBlock() in index.html,
// so the existing quiz renderer can consume it directly once the Vocab page (in
// nz-vocab-module.js, not included here) is wired to look for chapter.quiz.
//
// Plugs directly into the existing Vocab page (Level Select → Chapter Cards →
// List → Detail), which already reads from window.NZChapterData.
// ═══════════════════════════════════════════════════════════════════════════════
