      quiz: [
        { id: 'n2-w7-q1', question: '（　）意識に、爪をかんでしまう。', options: ['不', '無', '非', '未'], answer: 1, note: '無意識に = unconsciously.' },
        { id: 'n2-w7-q2', question: '大学の入学（　）を払い込んだ。', options: ['金', '料', '代', '賃'], answer: 0, note: '入学金 = an admission/enrollment fee (fixed compound).' },
        { id: 'n2-w7-q3', question: '時間（　）労働とは、言いかえると「残業」である。', options: ['他', '外', '超', '後'], answer: 1, note: '時間外労働 = overtime work.' },
        { id: 'n2-w7-q4', question: '平和な世の中になることは（　）人類共通の夢です。', options: ['各', '総', '全', '合'], answer: 2, note: '全人類 = all of humanity.' },
        { id: 'n2-w7-q5', question: '観客はフルートの（　）演奏に耳を傾けた。', options: ['名', '高', '有', '超'], answer: 0, note: '名演奏 = a masterful performance.' },
        { id: 'n2-w7-q6', question: '彼女は一流大学を出ているせいか、プライドが（　）。', options: ['軽い', '暗い', '高い', '多い'], answer: 2, note: 'プライドが高い = to be very proud/have high pride.' },
        { id: 'n2-w7-q7', question: '彼とは大学以来だから、会うのは20年（　）だ。', options: ['め', 'おき', 'ごと', 'ぶり'], answer: 3, note: '20年ぶり = after (an interval of) 20 years.' },
        { id: 'n2-w7-q8', question: '許可証の再（　）はできませんので、なくさないようにご注意ください。', options: ['発売', '販売', '生産', '発行'], answer: 3, note: '再発行 = reissuing (a license/permit).' },
        { id: 'n2-w7-q9', question: '（　）気持ちでOKと言ったが、引き受けなければよかった。', options: ['軽い', '重い', '高い', '低い'], answer: 0, note: '軽い気持ちで = without thinking much, casually.' },
        { id: 'n2-w7-q10', question: 'これ、賞味期限が（　）いるけれど、大丈夫かなあ。', options: ['切れて', 'なくなって', 'かけて', '取れて'], answer: 0, note: '賞味期限が切れる = a best-before date has expired.' },
        { id: 'n2-w7-q11', question: '物を見るときの目の様子。', options: ['目ぶり', '目つき', '目づかい', '目あたり'], answer: 1, note: '目つき = a look in one\'s eyes.' },
        { id: 'n2-w7-q12', question: '知識や習慣などが自分自身のものとなる。', options: ['心につく', '体につく', '気につく', '身につく'], answer: 3, note: '身につく = to become one\'s own skill/habit.' },
        { id: 'n2-w7-q13', question: '意志や感情を伝えるための体の動き。', options: ['身ぶり', '体ぶり', '身づかい', '体づかい'], answer: 0, note: '身ぶり = gestures, body language.' },
        { id: 'n2-w7-q14', question: '人が突然、感情的になって怒り出したりする。', options: ['シメる', 'キレる', 'トレる', 'ツケる'], answer: 1, note: 'キレる = to "snap"/suddenly lose one\'s temper (slang).' },
        { id: 'n2-w7-q15', question: '季節が変化するちょうどその時。', options: ['季節の変わり間', '季節の変わり目', '季節の変化時', '季節の変化間'], answer: 1, note: '季節の変わり目 = the turning point between seasons.' },
        { id: 'n2-w7-q16', question: '飛行機は1時間＿おきに＿飛んでいます。', options: ['で', 'ごとに', '以内で', '以上'], answer: 1, note: 'ごとに ≈ おきに = every (interval).' },
        { id: 'n2-w7-q17', question: '＿レベルの高い＿大学だから、簡単には入れません。', options: ['授業料が高い', '難しい', '高級な', '豪華な'], answer: 1, note: 'レベルが高い (academically demanding) is closest to 難しい here — hard to get into.' },
        { id: 'n2-w7-q18', question: '模擬試験の結果から＿予測する＿と、合格は間違いないだろう。', options: ['見当をつける', '見方をつける', '合計を出す', '決心を出す'], answer: 0, note: '見当をつける ≈ 予測する = to make an educated guess.' },
        { id: 'n2-w7-q19', question: '薬の効果が＿なくなった＿のか、また歯が痛みだした。', options: ['かかった', 'あまった', 'きれた', 'すんだ'], answer: 2, note: '効果がきれる = the effect wears off/runs out.' },
        { id: 'n2-w7-q20', question: '学生のころはお金がなくて、＿つらい＿毎日だった。', options: ['はげしい', 'まずしい', 'きつい', 'つまらない'], answer: 2, note: 'つらい ≈ きつい = hard, tough (describing the days themselves).' },
        { id: 'n2-w7-q21', question: '「超」の正しい使い方は？', options: ['あまり超カロリーの食事を取るのは体に良くない。', '彼女は世界的な超女優です。', '超気圧のせいで今日は天気がとてもよい。', '新幹線は以前、「夢の超特急」と呼ばれていたことがあった。'], answer: 3, note: '超特急 = a super-express train — a fixed, natural compound (unlike 超カロリー, 超女優, 超気圧 which aren\'t standard).' },
        { id: 'n2-w7-q22', question: '「賃」の正しい使い方は？', options: ['アメリカに荷物を送るときの運送賃はとても高い。', '車の修理賃はおいくらですか。', '地下鉄の乗り賃が値上げされた。', '家は広いが、遠くなったので電車賃が前よりかかる。'], answer: 3, note: '電車賃 = train fare — a standard, natural compound (unlike 運送賃, 修理賃, 乗り賃 which sound unnatural; the standard words are 送料, 修理代, 運賃).' },
        { id: 'n2-w7-q23', question: '「風」の正しい使い方は？', options: ['この店のうどんは関東風のつゆで色が黒い。', '公園で日常風に犬の散歩をさせています。', 'その衣装は見た風がちょっと悪いね。', 'これは立体風があるいい絵だと思います。'], answer: 0, note: '関東風 = Kanto-style — correct, natural usage of 〜風 meaning "in the style of".' },
        { id: 'n2-w7-q24', question: '「ごとに」の正しい使い方は？', options: ['一日ごとにお風呂に入ります。', '私は、いつもリンゴを皮ごとに食べる。', 'この機械は、一台売れるごとに多くの利益が出る。', '先生が言ったごとに勉強しています。'], answer: 2, note: '〜ごとに after a verb (売れるごとに) = "each time X happens" — correct usage.' },
        { id: 'n2-w7-q25', question: '「たて」の正しい使い方は？', options: ['彼の話したては父親にそっくりだ。', 'ご飯を食べたてにして、どこへ行くの。', 'パソコンを使いたてにするのは難しい。', '料理はできたてがおいしい。'], answer: 3, note: 'できたて = freshly made — correct, natural usage (like 焼きたて, 炊きたて).' },
        { id: 'n2-w7-q26', question: '電源を（　）ので、パソコンが動かない。', options: ['切れた', 'つけた', 'かけた', '取った'], answer: 0, note: '電源が切れる = the power goes out/is cut.' },
        { id: 'n2-w7-q27', question: '難しい仕事だが、なんとか（　）がついてきた。', options: ['めど', '差', '味', '折り目'], answer: 0, note: 'めどがつく = there\'s a prospect of solving something.' },
        { id: 'n2-w7-q28', question: 'すでに亡くなった（　）大臣の功績をたたえる。', options: ['現', '前', '元', '故'], answer: 3, note: '故〜 = the late (deceased) — used for someone who has passed away.' },
        { id: 'n2-w7-q29', question: '彼は忘れ（　）思い出を大切にしている。', options: ['がたい', 'づらい', 'やすい', 'にくい'], answer: 0, note: '忘れがたい = unforgettable.' },
        { id: 'n2-w7-q30', question: 'このパンは焼き（　）で、とてもおいしい。', options: ['たて', 'つき', 'ごと', 'おき'], answer: 0, note: '焼きたて = freshly baked.' }
      ]
